#include <stdio.h>
#include <stdlib.h>

#define MAXN 1000
#define MAXM 100000

struct Edge { int u, v, w; } edges[MAXM];
int fa[MAXN];

int find(int x) {                    /* 并查集: 路径压缩, 近似 O(1) */
    while (fa[x] != x) { fa[x] = fa[fa[x]]; x = fa[x]; }
    return x;
}

int cmp(const void *a, const void *b) {
    return ((struct Edge *)a)->w - ((struct Edge *)b)->w;   /* 按权升序 */
}

int main(void) {
    int n, m, i, total = 0, cnt = 0;
    printf("输入顶点数 n 边数 m: ");
    scanf("%d %d", &n, &m);
    printf("输入 %d 条边 (u v w, 无向带权):\n", m);
    for (i = 0; i < m; i++) scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);

    qsort(edges, m, sizeof(struct Edge), cmp);   /* 排序 O(m log m) */
    for (i = 0; i < n; i++) fa[i] = i;

    printf("\n选中的边:\n");
    for (i = 0; i < m && cnt < n - 1; i++) {
        int ru = find(edges[i].u), rv = find(edges[i].v);
        if (ru != rv) {                          /* 两端不同块才选, 不成环 */
            fa[ru] = rv;                         /* 合并连通块 */
            total += edges[i].w;
            cnt++;
            printf("(%d, %d) w=%d\n", edges[i].u, edges[i].v, edges[i].w);
        }
    }
    if (cnt < n - 1) { printf("图不连通, 不存在最小生成树\n"); return 0; }
    printf("最小生成树总权值: %d\n", total);
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 1000
#define MAXM 100000
#define INF 0x3f3f3f3f

int main(void) {
    int n, m, s, i, j;
    int u[MAXM], v[MAXM], w[MAXM];     /* 边表: Bellman-Ford 无需邻接表 */
    int dist[MAXN], parent[MAXN];
    int has_neg_cycle = 0;

    printf("输入顶点数 n 边数 m 源点 s: ");
    scanf("%d %d %d", &n, &m, &s);
    printf("输入 %d 条边 (u v w, 允许负权):\n", m);
    for (i = 0; i < m; i++) scanf("%d %d %d", &u[i], &v[i], &w[i]);

    memset(dist, 0x3f, sizeof(dist));  /* 初始为无穷大 */
    memset(parent, -1, sizeof(parent));
    dist[s] = 0;

    /* n-1 轮松弛: 第 k 轮后 dist 为至多用 k 条边的最短路 */
    for (i = 0; i < n - 1; i++) {
        int changed = 0;
        for (j = 0; j < m; j++) {
            if (dist[u[j]] != INF && (long long)dist[u[j]] + w[j] < dist[v[j]]) {
                dist[v[j]] = dist[u[j]] + w[j];
                parent[v[j]] = u[j];
                changed = 1;
            }
        }
        if (!changed) break;           /* 提前收敛, 可提前退出 */
    }

    /* 第 n 轮: 仍能松弛 => 存在从 s 可达的负权环 */
    for (j = 0; j < m; j++)
        if (dist[u[j]] != INF && (long long)dist[u[j]] + w[j] < dist[v[j]])
            has_neg_cycle = 1;

    if (has_neg_cycle) { printf("存在从源点可达的负权环, 无最短路\n"); return 0; }
    printf("\n从 %d 出发的最短路:\n", s);
    for (i = 0; i < n; i++) {
        if (dist[i] == INF) { printf("v%d: 不可达\n", i); continue; }
        printf("v%d: dist = %d\n", i, dist[i]);
    }
    return 0;
}

#include <stdio.h>

#define MAXN 500
#define INF 0x3f3f3f3f

int d[MAXN][MAXN];

int main(void) {
    int n, m, i, j, k, u, v, w;

    printf("输入顶点数 n 边数 m: ");
    scanf("%d %d", &n, &m);
    for (i = 0; i < n; i++)
        for (j = 0; j < n; j++)
            d[i][j] = (i == j) ? 0 : INF;

    printf("输入 %d 条边 (u v w, 允许负权, 但不得有负环):\n", m);
    for (i = 0; i < m; i++) {
        scanf("%d %d %d", &u, &v, &w);
        if (w < d[u][v]) d[u][v] = w;          /* 重边取最小 */
    }

    /* 最外层 k: 依次允许顶点 0..k 作为中间点, 原地更新安全 */
    for (k = 0; k < n; k++)
        for (i = 0; i < n; i++) {
            if (d[i][k] == INF) continue;
            for (j = 0; j < n; j++)
                if (d[k][j] != INF && d[i][j] > (long long)d[i][k] + d[k][j])
                    d[i][j] = d[i][k] + d[k][j];
        }

    for (i = 0; i < n; i++)
        if (d[i][i] < 0) { printf("存在负权环\n"); return 0; }

    printf("\n全源最短路矩阵 (INF 表示不可达):\n");
    for (i = 0; i < n; i++) {
        for (j = 0; j < n; j++) {
            if (d[i][j] == INF) printf(" INF ");
            else printf("%4d ", d[i][j]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXN 500
#define INF 0x3f3f3f3f

int cap[MAXN][MAXN];       /* 容量(含反向边, 全局自动初始化为 0) */
int n, m, s, t;

int bfs_augment(void) {    /* BFS 找一条最短(边数最少)增广路, 返回增广量 */
    static int q[MAXN], pre[MAXN], vis[MAXN];
    int qh = 0, qt = 0, u, v;
    memset(vis, 0, sizeof(vis));
    vis[s] = 1; pre[s] = -1; q[qt++] = s;
    while (qh < qt) {
        u = q[qh++];
        for (v = 0; v < n; v++)
            if (!vis[v] && cap[u][v] > 0) {   /* 残量大于 0 才可走 */
                vis[v] = 1; pre[v] = u;
                q[qt++] = v;
            }
    }
    if (!vis[t]) return 0;                  /* 无增广路, 已达最大流 */
    int d = INF;
    for (v = t; v != s; v = pre[v])
        if (cap[pre[v]][v] < d) d = cap[pre[v]][v];
    for (v = t; v != s; v = pre[v]) {
        cap[pre[v]][v] -= d;                /* 正向残量减 */
        cap[v][pre[v]] += d;                /* 反向残量加(可退回) */
    }
    return d;
}

int main(void) {
    int u, v, c, flow = 0, d;
    printf("输入顶点数 n 边数 m 源点 s 汇点 t: ");
    scanf("%d %d %d %d", &n, &m, &s, &t);
    printf("输入 %d 条边 (u v c, 容量):\n", m);
    for (int i = 0; i < m; i++) {
        scanf("%d %d %d", &u, &v, &c);
        cap[u][v] += c;                     /* 重边容量合并 */
    }
    while ((d = bfs_augment()) > 0) flow += d;   /* 增广次数 O(V*E) */
    printf("最大流: %d\n", flow);
    return 0;
}

# Dinic: BFS 分层 + DFS 多路增广(阻塞流), 复杂度 O(V^2 * E)
from collections import deque
import sys
sys.setrecursionlimit(100000)

class Dinic:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]   # 边: [to, rev, cap]
    def add_edge(self, u, v, c):
        self.adj[u].append([v, len(self.adj[v]), c])
        self.adj[v].append([u, len(self.adj[u]) - 1, 0])   # 反向边容量 0
    def bfs(self, s, t):                    # 建立分层图
        self.level = [-1] * self.n
        self.level[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for to, rev, cap in self.adj[u]:
                if cap > 0 and self.level[to] < 0:
                    self.level[to] = self.level[u] + 1
                    q.append(to)
        return self.level[t] >= 0
    def dfs(self, u, t, f):                 # 在分层图上推流(阻塞流)
        if u == t:
            return f
        while self.it[u] < len(self.adj[u]):
            to, rev, cap = self.adj[u][self.it[u]]
            if cap > 0 and self.level[to] == self.level[u] + 1:
                d = self.dfs(to, t, min(f, cap))
                if d > 0:
                    self.adj[u][self.it[u]][2] -= d   # 正向减
                    self.adj[to][rev][2] += d         # 反向加
                    return d
            self.it[u] += 1                 # 此边已无潜力, 跳过
        return 0
    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, float("inf"))
                if f == 0:
                    break
                flow += f
        return flow

n, m, s, t = map(int, input("输入顶点数 n 边数 m 源点 s 汇点 t: ").split())
g = Dinic(n)
print(f"输入 {m} 条边 (u v c, 容量):")
for _ in range(m):
    u, v, c = map(int, input().split())
    g.add_edge(u, v, c)
print("最大流:", g.max_flow(s, t))

#include <stdio.h>
#include <string.h>

#define MAXN 500
#define MAXM 50000

int head[MAXN], to[MAXM], nxt[MAXM], ecnt;   /* 邻接表: 只存 X -> Y 的边 */
int matchY[MAXN];        /* matchY[y] = x, 表示 y 已匹配给 x */
int vis[MAXN];           /* 本轮尝试中 y 是否已访问 */

int dfs(int x) {         /* 为 x 找增广路, 成功返回 1 */
    for (int e = head[x]; e != -1; e = nxt[e]) {
        int y = to[e];
        if (vis[y]) continue;                 /* 本轮已尝试, 防死循环 */
        vis[y] = 1;
        if (matchY[y] == -1 || dfs(matchY[y])) {
            matchY[y] = x;                    /* 翻转增广路 */
            return 1;
        }
    }
    return 0;
}

int main(void) {
    int n1, n2, m, i, x, y, ans = 0;
    printf("输入左部顶点数 n1 右部顶点数 n2 边数 m: ");
    scanf("%d %d %d", &n1, &n2, &m);
    memset(head, -1, sizeof(head));
    memset(matchY, -1, sizeof(matchY));
    printf("输入 %d 条边 (x y, x 属左部 0..n1-1, y 属右部 0..n2-1):\n", m);
    for (i = 0; i < m; i++) {
        scanf("%d %d", &x, &y);
        to[ecnt] = y; nxt[ecnt] = head[x]; head[x] = ecnt++;
    }

    for (x = 0; x < n1; x++) {                /* 每个左部顶点尝试匹配一次 */
        memset(vis, 0, sizeof(vis));          /* 每轮重置访问标记 */
        if (dfs(x)) ans++;
    }

    printf("最大匹配数: %d\n", ans);
    printf("匹配边:\n");
    for (y = 0; y < n2; y++)
        if (matchY[y] != -1) printf("(%d, %d)\n", matchY[y], y);
    return 0;
}

# 匈牙利算法: 二分图最大匹配(DFS 增广), O(V*E)
import sys
sys.setrecursionlimit(100000)

n1, n2, m = map(int, input("输入左部顶点数 n1 右部顶点数 n2 边数 m: ").split())
adj = [[] for _ in range(n1)]
print(f"输入 {m} 条边 (x y, x 属左部 0..n1-1, y 属右部 0..n2-1):")
for _ in range(m):
    x, y = map(int, input().split())
    adj[x].append(y)

match_y = [-1] * n2          # match_y[y] = x

def dfs(x, vis):
    for y in adj[x]:
        if vis[y]:
            continue
        vis[y] = True
        if match_y[y] == -1 or dfs(match_y[y], vis):
            match_y[y] = x   # 翻转增广路
            return True
    return False

ans = 0
for x in range(n1):
    vis = [False] * n2       # 每轮重置
    if dfs(x, vis):
        ans += 1

print(f"最大匹配数: {ans}")
print("匹配边:")
for y in range(n2):
    if match_y[y] != -1:
        print(f"({match_y[y]}, {y})")
